import { flushPromises, mount } from '@vue/test-utils'
import { createI18n } from 'vue-i18n'
import { afterEach, describe, expect, it, vi } from 'vitest'

import ChannelFormModal from '@/components/console/channels/ChannelFormModal.vue'
import type { AdminChannel } from '@/types/console'
// Generated by controller/frontend_contract_test.go from requests that the real
// UpdateChannel handler accepts.
import rootRename from '../../../../../tests/fixtures/native/channel-vertex-rename.put.request.json'
import adminRename from '../../../../../tests/fixtures/native/channel-vertex-rename-write-only.put.request.json'

const permissions = vi.hoisted(() => ({ sensitive: false }))
vi.mock('@/api/adminManagement', () => ({
  metadataApi: { groups: vi.fn().mockResolvedValue([]) },
}))
vi.mock('@/stores/auth', () => ({
  useAuthStore: () => ({
    isAdmin: true,
    hasPermission: (resource: string, action: string) =>
      resource === 'channel' &&
      (action === 'write' ||
        action === 'read' ||
        (action === 'sensitive_write' && permissions.sensitive)),
  }),
}))
vi.mock('@/stores/app', () => ({
  useAppStore: () => ({
    isFeatureEnabled: () => true,
    featureStatus: () => 'live',
  }),
}))

// The same stored channel the Go contract test inserts.
const vertex: AdminChannel = {
  id: rootRename.id,
  name: 'vertex-contract',
  type: 41,
  channel_ratio: '1',
  max_concurrency: 0,
  in_flight: 0,
  lab: { id: 'google', name: 'Google', source: 'vendor' },
  status: 1,
  priority: 5,
  weight: 2,
  used_quota: 0,
  balance: 0,
  response_time: 0,
  test_time: 0,
  base_url: '',
  models: 'gemini-2.5-pro',
  model_mapping: '',
  other: '{"default":"us-central1"}',
  settings: '{"vertex_key_type":"json"}',
}

async function rename(name: string) {
  const save = vi.fn().mockResolvedValue(true)
  const wrapper = mount(ChannelFormModal, {
    attachTo: document.body,
    props: { open: true, editing: vertex, save, fetchModels: vi.fn() },
    global: {
      plugins: [
        createI18n({
          legacy: false,
          locale: 'en',
          missingWarn: false,
          fallbackWarn: false,
        }),
      ],
    },
  })
  await flushPromises()
  const input = document.body.querySelector<HTMLInputElement>(
    '[role="dialog"] input[name="admin-channel-name"]'
  )!
  input.value = name
  input.dispatchEvent(new Event('input'))
  await flushPromises()
  ;[
    ...document.body.querySelectorAll<HTMLButtonElement>(
      '[role="dialog"] button'
    ),
  ]
    .find((button) => button.textContent?.includes('channels.saveChannel'))!
    .click()
  await flushPromises()
  wrapper.unmount()
  expect(save).toHaveBeenCalledOnce()
  // useAdminChannels.updateChannelDetails adds the id before the PUT.
  return { id: vertex.id, ...save.mock.calls[0]![0] }
}

afterEach(() => {
  permissions.sensitive = false
  document.body.innerHTML = ''
})

describe('channel update payload', () => {
  it('resends the unchanged Vertex region for a sensitive writer', async () => {
    permissions.sensitive = true
    expect(await rename(rootRename.name)).toEqual(rootRename)
  })

  it('omits the whole sensitive group without sensitive write', async () => {
    expect(await rename(adminRename.name)).toEqual(adminRename)
  })
})
